#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>

#define MAX_PATH 4096
#define MAX_CONTAINERS 64
#define CONTAINER_ROOT "/var/lib/containers"

typedef struct {
    char id[65];
    char rootfs[MAX_PATH];
    int status;
} container_t;

typedef struct {
    void (*callback)(void *ctx, const char *result);
    void *ctx;
    char path[MAX_PATH];
    char container_id[65];
    int resolved;
} async_task_t;

static container_t containers[MAX_CONTAINERS];
static int container_count = 0;
static pthread_mutex_t registry_lock = PTHREAD_MUTEX_INITIALIZER;

static int normalize_path_component(const char *input, char *output, size_t outlen) {
    size_t i = 0, j = 0;
    if (outlen == 0) return -1;
    while (input[i] && j < outlen - 1) {
        if (input[i] == '/' && input[i+1] == '/') {
            i++;
            continue;
        }
        output[j++] = input[i++];
    }
    output[j] = '\0';
    return 0;
}

static int resolve_container_path(const char *container_id, const char *subpath, char *resolved, size_t reslen) {
    char normalized[MAX_PATH];
    char fullpath[MAX_PATH];

    normalize_path_component(subpath, normalized, sizeof(normalized));

    /* Build the expected prefix */
    snprintf(fullpath, sizeof(fullpath), "%s/%s/rootfs/%s", CONTAINER_ROOT, container_id, normalized);

    /* Resolve symlinks */
    if (realpath(fullpath, resolved) == NULL) {
        /* If realpath fails, the path doesn't exist - reject it */
        return -1;
    }

    /* Verify the resolved path is within container boundaries */
    char expected_prefix[MAX_PATH];
    snprintf(expected_prefix, sizeof(expected_prefix), "%s/%s/rootfs", CONTAINER_ROOT, container_id);

    char resolved_prefix[MAX_PATH];
    if (realpath(expected_prefix, resolved_prefix) == NULL) {
        /* If prefix resolution fails, reject the request entirely */
        return -1;
    }

    if (strncmp(resolved, resolved_prefix, strlen(resolved_prefix)) != 0) {
        return -1;
    }
    return 0;
}

static void list_directory_contents(const char *path, char *buffer, size_t buflen) {
    DIR *dir = opendir(path);
    if (!dir) {
        snprintf(buffer, buflen, "error: cannot open directory: %s", strerror(errno));
        return;
    }

    size_t offset = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL && offset < buflen - 256) {
        if (entry->d_name[0] == '.') continue;
        struct stat st;
        char entpath[MAX_PATH];
        snprintf(entpath, sizeof(entpath), "%s/%s", path, entry->d_name);
        if (stat(entpath, &st) == 0) {
            int written = snprintf(buffer + offset, buflen - offset, "%s\t%ld\t%o\n",
                             entry->d_name, (long)st.st_size, st.st_mode & 0777);
            if (written < 0) {
                break;
            }
            /* snprintf returns the number of bytes that WOULD have been
             * written; clamp to the actual remaining space to avoid
             * advancing offset past the buffer and underflowing buflen-offset. */
            if ((size_t)written >= buflen - offset) {
                offset = buflen - 1;
                break;
            }
            offset += (size_t)written;
        }
    }
    closedir(dir);
}

static void *async_list_worker(void *arg) {
    async_task_t *task = (async_task_t *)arg;
    char resolved[MAX_PATH];
    char result[8192];

    memset(result, 0, sizeof(result));

    if (resolve_container_path(task->container_id, task->path, resolved, sizeof(resolved)) != 0) {
        snprintf(result, sizeof(result), "error: path traversal detected");
    } else {
        list_directory_contents(resolved, result, sizeof(result));
    }

    task->callback(task->ctx, result);
    task->resolved = 1;
    return NULL;
}

typedef struct {
    char output[8192];
    int done;
} list_context_t;

static void list_callback(void *ctx, const char *result) {
    list_context_t *lctx = (list_context_t *)ctx;
    strncpy(lctx->output, result, sizeof(lctx->output) - 1);
    lctx->done = 1;
}

int container_list_path(const char *container_id, const char *path, char *output, size_t outlen) {
    /* Validate container exists */
    int found = 0;
    pthread_mutex_lock(&registry_lock);
    for (int i = 0; i < container_count; i++) {
        if (strcmp(containers[i].id, container_id) == 0) {
            found = 1;
            break;
        }
    }
    pthread_mutex_unlock(&registry_lock);

    if (!found) {
        snprintf(output, outlen, "error: container not found");
        return -1;
    }

    list_context_t ctx;
    memset(&ctx, 0, sizeof(ctx));

    async_task_t task;
    memset(&task, 0, sizeof(task));
    strncpy(task.container_id, container_id, sizeof(task.container_id) - 1);
    strncpy(task.path, path, sizeof(task.path) - 1);
    task.callback = list_callback;
    task.ctx = &ctx;
    task.resolved = 0;

    pthread_t tid;
    if (pthread_create(&tid, NULL, async_list_worker, &task) != 0) {
        snprintf(output, outlen, "error: failed to create worker");
        return -1;
    }

    pthread_join(tid, NULL);

    strncpy(output, ctx.output, outlen - 1);
    output[outlen - 1] = '\0';
    return 0;
}

int register_container(const char *id, const char *rootfs_path) {
    pthread_mutex_lock(&registry_lock);
    if (container_count >= MAX_CONTAINERS) {
        pthread_mutex_unlock(&registry_lock);
        return -1;
    }
    strncpy(containers[container_count].id, id, sizeof(containers[container_count].id) - 1);
    containers[container_count].id[sizeof(containers[container_count].id) - 1] = '\0';
    strncpy(containers[container_count].rootfs, rootfs_path, MAX_PATH - 1);
    containers[container_count].rootfs[MAX_PATH - 1] = '\0';
    containers[container_count].status = 1;
    container_count++;
    pthread_mutex_unlock(&registry_lock);
    return 0;
}
